4	const MAX_BODY_BYTES = 1024 * 1024;
5	const ETAG_PATTERN = /^"[0-9a-f]{64}"$/u;
6	const ID_PATTERN = /^[a-z0-9][a-z0-9._-]*$/u;
7	const DOCUMENT_FIELDS = new Set(['id', 'title', 'body', 'tags']);
