27	  if (Number.isFinite(declared) && declared > MAX_BODY_BYTES) {
28	    req.resume();
29	    throw new HttpError(413, 'PAYLOAD_TOO_LARGE', 'request body exceeds 1 MiB');
30	  }
31	  const chunks = [];
32	  let size = 0;
33	  for await (const chunk of req) {
34	    size += chunk.length;
35	    if (size > MAX_BODY_BYTES) {
36	      throw new HttpError(413, 'PAYLOAD_TOO_LARGE', 'request body exceeds 1 MiB');
37	    }
38	    chunks.push(chunk);
39	  }
40	  return Buffer.concat(chunks).toString('utf8');
41	}
42	
43	function parseJson(text) {
44	  try {
45	    return JSON.parse(text);
46	  } catch {
47	    throw new HttpError(400, 'INVALID_JSON', 'request body is not valid JSON');
48	  }
49	}
