51	function validateDocument(data) {
52	  if (!data || typeof data !== 'object' || Array.isArray(data)) {
53	    throw new HttpError(400, 'INVALID_DOCUMENT', 'document must be an object');
54	  }
55	  for (const key of Object.keys(data)) {
56	    if (!DOCUMENT_FIELDS.has(key)) {
57	      throw new HttpError(400, 'INVALID_DOCUMENT', `unknown document field: ${key}`);
58	    }
59	  }
60	  for (const key of ['id', 'title', 'body']) {
61	    if (typeof data[key] !== 'string' || !data[key].trim()) {
62	      throw new HttpError(400, 'INVALID_DOCUMENT', `${key} must be a non-empty string`);
63	    }
64	  }
65	  if (!ID_PATTERN.test(data.id)) {
66	    throw new HttpError(400, 'INVALID_DOCUMENT', 'id must be URL-safe lowercase text');
67	  }
68	  if (data.tags !== undefined && (!Array.isArray(data.tags) || data.tags.some((tag) => typeof tag !== 'string'))) {
69	    throw new HttpError(400, 'INVALID_DOCUMENT', 'tags must be an array of strings');
70	  }
71	  return { id: data.id, title: data.title, body: data.body, tags: data.tags ?? [] };
72	}
73	
74	// A document server holds one Workspace and persists every committed change
75	// through `save(snapshot)` before the in-memory state is swapped, so a failed
76	// save leaves memory, queries, and the original file untouched.
77	export function createDocumentServer({ workspace, save }) {
78	  let current = workspace;
79	
80	  const currentEtag = () => `"${current.exportJSON().checksum}"`;
81	
82	  function requireIfMatch(req) {
83	    const value = req.headers['if-match'];
84	    if (value === undefined) {
85	      throw new HttpError(428, 'PRECONDITION_REQUIRED', 'write requests require an If-Match header');
86	    }
87	    if (!ETAG_PATTERN.test(value)) {
88	      throw new HttpError(400, 'INVALID_IF_MATCH', 'If-Match must be a double-quoted checksum');
89	    }
90	    if (value !== currentEtag()) {
91	      throw new HttpError(412, 'PRECONDITION_FAILED', 'If-Match checksum is stale');
92	    }
93	  }
94	
95	  function assertTitleFree(candidate, title) {
96	    const trimmed = title.trim();
97	    for (const existing of candidate.list()) {
98	      if (existing.title === trimmed) {
99	        throw new HttpError(409, 'CONFLICT', `title already in use: ${trimmed}`);
100	      }
101	    }
102	  }
103	
104	  // Builds the next state on a candidate workspace, persists its version-1
105	  // snapshot, and only then installs it. Everything here is synchronous, so a
106	  // commit is atomic with respect to other requests.
107	  function commit(mutate) {
108	    const candidate = new Workspace();
109	    for (const document of current.list()) candidate.add(document);
110	    mutate(candidate);
111	    const snapshot = candidate.exportJSON();
112	    save(snapshot);
113	    current = candidate;
114	    return snapshot;
115	  }
116	
117	  async function createDocument(req, res) {
118	    const text = await readBody(req);
119	    requireIfMatch(req);
120	    const document = validateDocument(parseJson(text));
121	    const snapshot = commit((candidate) => {
122	      if (candidate.get(document.id)) {
123	        throw new HttpError(409, 'CONFLICT', `document already exists: ${document.id}`);
124	      }
125	      assertTitleFree(candidate, document.title);
126	      candidate.add(document);
127	    });
128	    sendJson(res, 201, snapshot, `"${snapshot.checksum}"`);
129	  }
130	
131	  async function replaceDocument(req, res, id) {
132	    const text = await readBody(req);
133	    requireIfMatch(req);
134	    const document = validateDocument(parseJson(text));
135	    if (document.id !== id) {
136	      throw new HttpError(400, 'ID_MISMATCH', `path id ${id} does not match body id ${document.id}`);
137	    }
138	    if (!current.get(id)) {
139	      throw new HttpError(404, 'NOT_FOUND', `document not found: ${id}`);
140	    }
141	    const snapshot = commit((candidate) => {
142	      candidate.remove(id);
143	      assertTitleFree(candidate, document.title);
144	      candidate.add(document);
145	    });
146	    sendJson(res, 200, snapshot, `"${snapshot.checksum}"`);
147	  }
148	
149	  function deleteDocument(req, res, id) {
150	    requireIfMatch(req);
151	    if (!current.get(id)) {
152	      throw new HttpError(404, 'NOT_FOUND', `document not found: ${id}`);
153	    }
154	    const snapshot = commit((candidate) => {
155	      candidate.remove(id);
156	    });
157	    sendJson(res, 200, snapshot, `"${snapshot.checksum}"`);
158	  }
159	
160	  async function handle(req, res) {
161	    const url = new URL(req.url, 'http://127.0.0.1');
162	    const segments = url.pathname.split('/').filter(Boolean).map(decodeURIComponent);
163	    const [resource, id, relation] = segments;
164	
165	    if (resource === 'documents' && segments.length === 1) {
166	      if (req.method === 'GET') {
167	        sendJson(res, 200, current.list(), currentEtag());
168	        return;
169	      }
170	      if (req.method === 'POST') {
171	        await createDocument(req, res);
172	        return;
173	      }
174	    } else if (resource === 'documents' && segments.length === 2) {
175	      if (req.method === 'GET') {
176	        const document = current.get(id);
177	        if (!document) throw new HttpError(404, 'NOT_FOUND', `document not found: ${id}`);
178	        sendJson(res, 200, document, currentEtag());
179	        return;
180	      }
181	      if (req.method === 'PUT') {
182	        await replaceDocument(req, res, id);
183	        return;
184	      }
185	      if (req.method === 'DELETE') {
186	        deleteDocument(req, res, id);
187	        return;
188	      }
189	    } else if (resource === 'documents' && segments.length === 3 && relation === 'links' && req.method === 'GET') {
190	      const links = current.links(id);
191	      if (!links) throw new HttpError(404, 'NOT_FOUND', `document not found: ${id}`);
192	      sendJson(res, 200, links, currentEtag());
193	      return;
194	    } else if (resource === 'search' && segments.length === 1 && req.method === 'GET') {
195	      sendJson(res, 200, current.search(url.searchParams.get('q') ?? ''), currentEtag());
196	      return;
197	    }
198	    throw new HttpError(404, 'NOT_FOUND', `no route for ${req.method} ${url.pathname}`);
199	  }
200	
201	  const server = http.createServer((req, res) => {
202	    handle(req, res).catch((error) => {
203	      if (res.headersSent) {
204	        res.destroy(error);
205	        return;
206	      }
207	      const status = error instanceof HttpError ? error.status : 500;
208	      const code = error instanceof HttpError ? error.code
209	        : error instanceof SnapshotError ? error.code
210	          : 'INTERNAL_ERROR';
211	      sendJson(res, status, { code, message: error.message });
212	    });
213	  });
214	  return server;
215	}
