    workspace,
    save: (snapshot) => atomicWrite(file, `${JSON.stringify(snapshot)}\n`),
  });
  server.on('error', (error) => {
    reportError(new SnapshotError('IO_ERROR', `cannot serve ${file}: ${error.message}`));
  });
