const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');

const CLI = '/opt/gsb-production/workspaces/sl-chen/prod-04/B/task003/src/cli.js';
const snapFile = path.join('/tmp/lattice-e2e', 'snap.json');
const histFile = path.join('/tmp/lattice-e2e', 'history.json');
try { fs.unlinkSync(snapFile); } catch {}
try { fs.unlinkSync(histFile); } catch {}

const child = spawn(process.execPath, [CLI, 'serve', snapFile, '--history', histFile, '--port', '0'], { stdio: ['ignore', 'pipe', 'pipe'] });
let stdout = '', stderr = '';
child.stdout.on('data', c => stdout += c);
child.stderr.on('data', c => stderr += c);

child.stdout.on('data', async () => {
  if (!stdout.includes('\n')) return;
  const addr = JSON.parse(stdout.split('\n')[0]);
  const base = 'http://127.0.0.1:' + addr.port;
  console.log('Server on port', addr.port);

  async function req(method, route, body, etag) {
    const headers = {};
    if (body) headers['content-type'] = 'application/json';
    if (etag) headers['if-match'] = etag;
    const res = await fetch(base + route, { method, headers, body: body ? JSON.stringify(body) : undefined });
    const text = await res.text();
    return { status: res.status, etag: res.headers.get('etag'), body: text ? JSON.parse(text) : null };
  }

  try {
    let r = await req('GET', '/documents');
    console.log('GET /documents:', r.status, r.body.length);
    const etag = r.etag;

    r = await req('POST', '/documents', { id: 'welcome', title: 'Welcome', body: 'Hello [[world]]', tags: ['Intro'] }, etag);
    console.log('POST /documents:', r.status, r.body.documents[0].tags);

    r = await req('GET', '/documents/welcome/history');
    console.log('History:', JSON.stringify(r.body.map(x => ({ rev: x.revision, action: x.action }))));

    r = await req('PUT', '/documents/welcome', { id: 'welcome', title: 'Welcome v2', body: 'Updated body', tags: ['Intro', 'Guide'] }, r.etag);
    console.log('PUT:', r.status, r.body.documents[0].title, r.body.documents[0].tags);

    r = await req('POST', '/documents/welcome/restore', { revision: 1 }, r.etag);
    console.log('Restore:', r.status, r.body.documents[0].title, r.body.documents[0].body, r.body.documents[0].tags);

    r = await req('GET', '/documents/welcome/history');
    console.log('Final history:', JSON.stringify(r.body.map(x => ({ rev: x.revision, action: x.action }))));

    r = await req('POST', '/documents/welcome/restore', { revision: 0 }, r.etag);
    console.log('Bad restore:', r.status, r.body.code);

    // Check files
    const hist = JSON.parse(fs.readFileSync(histFile, 'utf8'));
    console.log('History file: version', hist.version, 'records', hist.documents.welcome.map(x => x.action));
    const snap = JSON.parse(fs.readFileSync(snapFile, 'utf8'));
    console.log('Snapshot file: version', snap.version, 'docs', snap.documents.map(d => d.id));
    console.log('ALL OK');
  } catch (e) {
    console.error('TEST FAILED:', e.message);
  } finally {
    child.kill('SIGKILL');
  }
});

child.on('exit', code => {
  if (code && code !== 0) console.error('Server exited with', code, stderr);
});
